package net.civeira.phylax.feature.observe.observedalertrule.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedAlertRuleChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_alert_rule_change_set_builder() {
    ObservedAlertRuleChangeSet one = new ObservedAlertRuleChangeSet().uid("one").name("one")
        .trigger(ObservedAlertRuleTriggerOptions.NEW_ISSUE)
        .origin(ObservedSourceReference.of("one")).minLevel(ObservedAlertRuleMinLevelOptions.ERROR)
        .threshold(1).windowMinutes(1).channel(ObservedAlertRuleChannelOptions.LOG).target("one")
        .cooldownMinutes(1).mutedUntil(LocalDateTime.of(1980, 8, 20, 0, 0)
            .atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime())
        .enabled(true).version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getName().get(), "Value must equals to the intial value");
    one.name("two");
    Assertions.assertEquals("two", one.getName().get(), "Value must equals to the assigned value");
    one.unset("name");
    Assertions.assertFalse(one.getName().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedAlertRuleTriggerOptions.NEW_ISSUE, one.getTrigger().get(),
        "Value must equals to the intial value");
    one.trigger(ObservedAlertRuleTriggerOptions.REGRESSION);
    Assertions.assertEquals(ObservedAlertRuleTriggerOptions.REGRESSION, one.getTrigger().get(),
        "Value must equals to the assigned value");
    one.unset("trigger");
    Assertions.assertFalse(one.getTrigger().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedSourceReference.of("one"), one.getOrigin().get(),
        "Value must equals to the intial value");
    one.origin(ObservedSourceReference.of("two"));
    Assertions.assertEquals(ObservedSourceReference.of("two"), one.getOrigin().get(),
        "Value must equals to the assigned value");
    one.unset("origin");
    Assertions.assertFalse(one.getOrigin().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedAlertRuleMinLevelOptions.ERROR, one.getMinLevel().get(),
        "Value must equals to the intial value");
    one.minLevel(ObservedAlertRuleMinLevelOptions.FATAL);
    Assertions.assertEquals(ObservedAlertRuleMinLevelOptions.FATAL, one.getMinLevel().get(),
        "Value must equals to the assigned value");
    one.unset("minLevel");
    Assertions.assertFalse(one.getMinLevel().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getThreshold().get(), "Value must equals to the intial value");
    one.threshold(2);
    Assertions.assertEquals(2, one.getThreshold().get(), "Value must equals to the assigned value");
    one.unset("threshold");
    Assertions.assertFalse(one.getThreshold().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getWindowMinutes().get(),
        "Value must equals to the intial value");
    one.windowMinutes(2);
    Assertions.assertEquals(2, one.getWindowMinutes().get(),
        "Value must equals to the assigned value");
    one.unset("windowMinutes");
    Assertions.assertFalse(one.getWindowMinutes().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedAlertRuleChannelOptions.LOG, one.getChannel().get(),
        "Value must equals to the intial value");
    one.channel(ObservedAlertRuleChannelOptions.WEBHOOK);
    Assertions.assertEquals(ObservedAlertRuleChannelOptions.WEBHOOK, one.getChannel().get(),
        "Value must equals to the assigned value");
    one.unset("channel");
    Assertions.assertFalse(one.getChannel().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getTarget().get(), "Value must equals to the intial value");
    one.target("two");
    Assertions.assertEquals("two", one.getTarget().get(),
        "Value must equals to the assigned value");
    one.unset("target");
    Assertions.assertFalse(one.getTarget().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getCooldownMinutes().get(),
        "Value must equals to the intial value");
    one.cooldownMinutes(2);
    Assertions.assertEquals(2, one.getCooldownMinutes().get(),
        "Value must equals to the assigned value");
    one.unset("cooldownMinutes");
    Assertions.assertFalse(one.getCooldownMinutes().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getMutedUntil().get(), "Value must equals to the intial value");
    one.mutedUntil(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getMutedUntil().get(), "Value must equals to the assigned value");
    one.unset("mutedUntil");
    Assertions.assertFalse(one.getMutedUntil().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getEnabled().get(), "Value must equals to the intial value");
    one.enabled(false);
    Assertions.assertEquals(false, one.getEnabled().get(),
        "Value must equals to the assigned value");
    one.unset("enabled");
    Assertions.assertFalse(one.getEnabled().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
